describe('CSV Import Feature', () => {
  beforeEach(() => {
    cy.visit('/records/import');
  });

  it('should successfully import records from a valid CSV file', () => {
    // Setup: intercept the file upload API
    cy.intercept('POST', '/api/records/import').as('importCsv');

    // Get the file input element
    cy.get('[data-testid="csv-file-input"]').selectFile('cypress/fixtures/valid_records.csv', { force: true });

    // Verify file is selected
    cy.get('[data-testid="file-preview"]').should('be.visible');
    cy.get('[data-testid="file-preview"]').should('contain', 'valid_records.csv');

    // Verify import button is enabled
    cy.get('[data-testid="import-button"]').should('be.visible');

    // Click import button
    cy.get('[data-testid="import-button"]').click();

    // Wait for API call
    cy.wait('@importCsv');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Records imported successfully');

    // Verify records are displayed
    cy.get('[data-testid="records-list"]').should('be.visible');
    cy.get('[data-testid="records-list"]').should('contain', '10 records');

    // Verify records have correct data
    cy.get('[data-testid="record-item"]').first().should('contain', 'John Doe');
    cy.get('[data-testid="record-item"]').last().should('contain', 'Jane Smith');
  });

  it('should handle invalid CSV file and display error message', () => {
    // Setup: intercept the file upload API
    cy.intercept('POST', '/api/records/import').as('importCsv');

    // Get the file input element
    cy.get('[data-testid="csv-file-input"]').selectFile('cypress/fixtures/invalid_records.csv', { force: true });

    // Verify file is selected
    cy.get('[data-testid="file-preview"]').should('be.visible');
    cy.get('[data-testid="file-preview"]').should('contain', 'invalid_records.csv');

    // Verify import button is enabled
    cy.get('[data-testid="import-button"]').should('be.visible');

    // Click import button
    cy.get('[data-testid="import-button"]').click();

    // Wait for API call
    cy.wait('@importCsv');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid CSV file format');

    // Verify import button is disabled
    cy.get('[data-testid="import-button"]').should('be.disabled');
  });
});
